    uint256 supply = 1000000 * 10**18;

    MockFactory mockFactory;
    MockRouter mockRouter;
    WETH mockWETH;

    function setUp() public {
        // Deploy mock contracts
        mockWETH = new WETH();
        mockFactory = new MockFactory();
        mockRouter = new MockRouter(address(mockFactory), address(mockWETH));

        // Fund owner
        vm.deal(owner, 10 ether);

        vm.startPrank(owner);
        token = new TokenTool{value: 1 ether}(
            "TestToken",
            "TEST",
            18,
            supply,
            address(mockRouter),
            owner,
            marketing,
            team,
            service
        );
        vm.stopPrank();
    }

    function test_SellTaxExceedsLimit() public {
        // Define string for final verdict
        string memory finalVerdict;

        // BEFORE: Query tax state
        console2.log("--- BEFORE-Trigger: Sell Tax State ---");
        uint256 liqBefore = token._sellLiquidityFee();
        uint256 marketingBefore = token._sellMarketingFee();
        uint256 teamBefore = token._sellTeamFee();
        uint256 totalTaxBefore = token._totalTaxIfSelling();
        uint256 computedTotalBefore = liqBefore + marketingBefore + teamBefore;

        console2.log("Liquidity fee:", liqBefore, "%");
        console2.log("Marketing fee:", marketingBefore, "%");
        console2.log("Team fee:", teamBefore, "%");
        console2.log("Total tax (function):", totalTaxBefore, "%");
        console2.log("Computed total:", computedTotalBefore, "%");

        // Trigger action: set sell taxes to extreme values
        console2.log("--- TRIGGER: Call setSelTaxes(30,30,30) ---");
        bool success;
        vm.startPrank(owner);
        try token.setSelTaxes(30,30,30) {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();

        if (!success) {
            console2.log("Result: Transaction reverted");
            finalVerdict = "Vulnerability not Exist: Failed to set sell taxes";
        } else {
            // AFTER: Query tax state again
            console2.log("--- AFTER-Trigger: Sell Tax State ---");
            uint256 liqAfter = token._sellLiquidityFee();
            uint256 marketingAfter = token._sellMarketingFee();
            uint256 teamAfter = token._sellTeamFee();
            uint256 totalTaxAfter = token._totalTaxIfSelling();
            uint256 computedTotalAfter = liqAfter + marketingAfter + teamAfter;

            console2.log("Liquidity fee:", liqAfter, "%");
            console2.log("Marketing fee:", marketingAfter, "%");
            console2.log("Team fee:", teamAfter, "%");
            console2.log("Total tax (function):", totalTaxAfter, "%");
            console2.log("Computed total:", computedTotalAfter, "%");

            // Verify tax rates were set to 30%
            if (liqAfter == 30 && marketingAfter == 30 && teamAfter == 30) {
                console2.log("Result: Tax rates successfully set to 30% each (total 90%)");
                finalVerdict = "Vulnerability Exists: Sell taxes can be set to extreme values (90%)";
            } else {
                console2.log("Result: Tax rates not set as expected");
                finalVerdict = string(abi.encodePacked(
                    "Vulnerability not Exist: Incorrect tax values (liq=",
                    vm.toString(liqAfter),
                    "%, mkt=",
                    vm.toString(marketingAfter),
                    "%, team=",
                    vm.toString(teamAfter),
                    "%)"
                ));
            }
        }

        // Final verdict
        console2.log(finalVerdict);
    }
}
```

**Key Modifications:**
1. **Before State Snapshot:** Queries all sell tax parameters (`_sellLiquidityFee`, `_sellMarketingFee`, `_sellTeamFee`, `_totalTaxIfSelling`) before the attack.
2. **Trigger Action:** The `setSelTaxes(30,30,30)` call is wrapped in a try-catch to detect reverts.
3. **After State Snapshot:** Re-queries the same parameters after the attack to detect changes.
4. **State Comparison:** Checks if all tax parameters were set to 30% as expected. 
5. **Vulnerability Verification:** 
   - If all taxes are 30% (total 90%), prints `Vulnerability Exists`.
   - If the call reverts or taxes aren't set correctly, prints `Vulnerability not Exist`.

**Differential Logic:**
- Success condition requires all taxes to be exactly 30% after the call.
- Reverts or incorrect values indicate the vulnerability doesn't exist.
- Final verdict provides explicit reasoning based on state changes.

